  const PAY_STEPS = [['variables', 'Variables du mois'], ['controles', 'Contrôles'], ['envoi', 'Envoi au prestataire'], ['bulletins', 'Bulletins']];
  const PAY_STATUS = { Préparation: 'warn', Envoyée: 'info', Reçue: 'accent', Diffusée: 'ok' };
