    return [a.cp ? `${a.cp} j CP` : '', a.rtt ? `${a.rtt} j RTT` : '', ...arr, a.unpaid ? `${a.unpaid} j sans solde` : '', a.tt ? `${a.tt} j télétravail` : ''].filter(Boolean).join(' · ') || '—';
