      const nk = nameKey({ firstName: r.prenom || '', lastName: r.nom || '' }), twin = !known.has(em) && db.employees.find((e) => e.stage < 15 && nameKey(e) === nk);
      if (twin && nk) errs.push(`${fullName(twin)} a déjà un dossier (${twin.email})`);
