      if (!(p.cloture >= 1 && p.cloture <= 28)) errs.push('Le jour de clôture est compris entre 1 et 28.'); if ([p.trValeur, p.trEmployeur, p.mutSal, p.mutEmp, p.ttJour].some((x) => !(x >= 0))) errs.push('Les montants sont des nombres positifs.');
